function rivalTeams(campers, rivalries) {
  const rivals = Array.from({ length: campers }, () => []);
  for (const [a, b] of rivalries) {
    rivals[a].push(b);
    rivals[b].push(a);
  }
  const cabin = new Array(campers).fill(-1);
  let camper = 0;
  while (camper >= 0 && camper < campers) {
    cabin[camper] += 1;
    if (cabin[camper] > 1) {
      cabin[camper] = -1;
      camper--;
      continue;
    }
    let clash = false;
    for (const other of rivals[camper]) {
      if (other < camper && cabin[other] === cabin[camper]) {
        clash = true;
        break;
      }
    }
    if (!clash) camper++;
  }
  return camper === campers;
}

function rivalTeams(campers, rivalries) {
  const rivals = Array.from({ length: campers }, () => []);
  for (const [a, b] of rivalries) {
    rivals[a].push(b);
    rivals[b].push(a);
  }
  const cabin = new Array(campers).fill(-1);
  for (let start = 0; start < campers; start++) {
    if (cabin[start] !== -1) continue;
    cabin[start] = 0;
    const queue = [start];
    for (let head = 0; head < queue.length; head++) {
      const camper = queue[head];
      for (const other of rivals[camper]) {
        if (cabin[other] === -1) {
          cabin[other] = 1 - cabin[camper];
          queue.push(other);
        } else if (cabin[other] === cabin[camper]) {
          return false;
        }
      }
    }
  }
  return true;
}
